/**
 * Foundations - documentation from absolute first principles.
 *
 * Written for readers who use software daily but have never worked with
 * AI models, agents, or developer tooling. Every term is defined the
 * first time it appears, every chapter explains WHY before HOW, and each
 * chapter builds on the previous one. Microsoft Style: active voice,
 * present tense, second person, one idea per sentence.
 *
 * These chapters form Part I of the manual; core chapters follow.
 */

import type { PdfChapter } from "./pdf";

const b = {
  p: (text: string) => ({ type: "p" as const, text }),
  h2: (text: string) => ({ type: "h2" as const, text }),
  h3: (text: string) => ({ type: "h3" as const, text }),
  bullet: (text: string) => ({ type: "bullet" as const, text }),
  note: (text: string) => ({ type: "note" as const, text }),
  code: (...lines: string[]) => ({ type: "code" as const, lines }),
};

