/** Alphabetical glossary chapter appended after foundations. */
export function buildGlossaryChapter(): PdfChapter {
  return {
    title: "Glossary",
    blocks: GLOSSARY.map(([term, def]) => ({
      type: "bullet" as const,
      text: `${term}: ${def}`,
    })),
  };
}

const GLOSSARY: Array<[string, string]> = [
  ["Attention", "The transformer mechanism: each token queries all others (via learned Query/Key/Value projections) and blends their information by relevance. Costs grow quadratically with sequence length."],
  ["Base model", "A model after pretraining only: superb at continuing text, not yet tuned to follow instructions."],
  ["CUDA / cuBLAS", "NVIDIA's GPU computing library and its tuned matrix-math library; the training and inference kernels for NVIDIA hardware."],
  ["Decontamination", "Removing benchmark test data from training sets so reported evaluation scores stay honest."],
  ["Dequantization", "Unpacking compressed (quantized) weights back to floating point before computation; the overhead that can make quantized models slower than FP16 on hardware without native kernels."],
  ["Distillation", "Training a smaller student model to imitate a larger teacher; smaller and cheaper, but not automatically faster or more concise on your hardware."],
  ["FP16", "Sixteen-bit floating point: full-precision weights for small models, executed natively by modern accelerators - sometimes the fastest option, not just the most accurate."],
  ["Fine-tuning", "Continuing training on a small curated dataset to teach a specific behavior; same math as pretraining, different data."],
  ["GLIBC", "The GNU C library - the basic services layer of Linux userspace. Old servers ship old GLIBC, which is why stitaP's legacy builds link statically against musl instead."],
  ["GPU compute libraries", "The tuned kernel libraries that execute attention and matrix math on accelerators: CUDA/cuBLAS (NVIDIA), ROCm (AMD), Metal (Apple), oneDNN/OpenVINO (Intel)."],
  ["Hallucination", "A confident, fluent, factually wrong output. Root cause: models predict plausibility, not truth."],
  ["Learning rate", "How far each training step moves parameters; too large destabilizes training, too small never converges."],
  ["LSTM", "Long short-term memory: a recurrent network with gates that improved memory over plain RNNs; the predecessor displaced by transformers."],
  ["N-gram model", "Early statistical predictor estimating the next word from the previous one or two; the direct ancestor of modern language models."],
  ["Pretraining", "The trillion-token next-token-prediction stage that produces a base model."],
  ["RLHF", "Reinforcement learning from human feedback: humans rank answers, a reward model learns the preferences, the main model optimizes against it."],
  ["Scaling laws", "The observed relationship that model quality improves predictably with compute, data, and parameters - the reason investment followed transformers."],
  ["SFT", "Supervised fine-tuning: training on example conversations so a base model learns the format of being an assistant."],
  ["Stochastic gradient descent", "The core training algorithm: measure the prediction error, nudge every parameter slightly to reduce it, repeat."],
  ["Token efficiency", "Useful output tokens divided by total tokens consumed. Raw-page dumping and retry storms push sessions under 2%; extraction, digests, and bounded retrieval keep them above 20%."],
  ["Transformer", "The 2017 architecture from 'Attention Is All You Need': reads all tokens in parallel with attention, enabling web-scale training. The foundation of every modern LLM."],
  ["Acceptance criteria", "The stated conditions under which a work item counts as done. Verification gates compare delivered evidence against them."],
  ["Agent", "Software that uses a model to decide actions, calls tools to perform them, and repeats until a goal is met."],
  ["AGI-free zone", "A promise: nothing here claims general intelligence. Every module does a defined job."],
  ["Approval gate", "A checkpoint that pauses risky agent actions until a person approves, rejects, or lets them expire."],
  ["Backend", "A specific runtime that generates tokens, such as llama.cpp on CPU or OpenVINO on NPU."],
  ["Benchmark cache", "Saved measurement results keyed to your hardware, so backend selection does not re-test on every launch."],
  ["Blackboard", "The shared message board where swarm workers post short summaries of what they produced."],
  ["Checkpoint", "A saved snapshot of progress that allows resuming after interruption."],
  ["Context overhead", "The number of tokens a module adds to every session prompt while enabled."],
  ["Context window", "The maximum tokens a model considers at once; its working memory."],
  ["Cron", "A scheduling format describing recurring times, such as every 15 minutes on weekdays."],
  ["Digest", "A compressed summary of an event or artifact, sized to cost tens of tokens instead of thousands."],
  ["Embedding", "A numeric representation of text used to measure similarity for retrieval."],
  ["Executor", "The function that performs a tool's work when invoked."],
  ["Fail soft", "Design rule: missing capability produces a reported limitation, never a crash."],
  ["Git", "The standard system for recording file changes; agents commit their work through it."],
  ["Guideline pack", "Your company's standards, loaded once and delivered to each agent role in relevant, token-capped portions."],
  ["Guest worker", "Informal term for a sub-swarm spawned for one bounded subtask."],
  ["Harness", "The system around agents: tools, permissions, budgets, tracing, and gates. stitaP is a harness."],
  ["Inference", "Running a trained model to produce output."],
  ["Jira ticket", "A tracked work item with comments and state, updated automatically by governed runs."],
  ["Kanban board", "Columns of work items moving from To Do toward Done; agents use boards like human teams."],
  ["Knowledge base", "stitaP's local retrieval store: ingest documents, retrieve passages within a token budget."],
  ["LLM", "Large language model: a model trained on vast text that predicts plausible continuations."],
  ["Manifest", "A tool's declaration card: id, parameters, outputs, permissions, supported backends."],
  ["Migration project", "A governed body of work converting software between languages or versions via user stories."],
  ["Module", "A bundled capability set that can be toggled per session; contributes tools plus instruction tokens."],
  ["NPU", "Neural processing unit: a chip specialized for AI math, emphasizing efficiency per watt."],
  ["NUMA", "Memory layout on multi-socket servers; ignoring it halves effective throughput."],
  ["Preset", "A named starting combination of session modules, such as SLM Minimal."],
  ["Quantization", "Storing model numbers with reduced precision to shrink size and speed up inference."],
  ["KV cache", "The notes a model keeps about every token it has read, so it does not re-read the conversation for each new token. It grows with the conversation, is not shrunk by weight quantization, and on long sessions can rival the weights in memory."],
  ["Swapping", "When RAM runs out, the operating system moves memory to disk. The program keeps running but slows by orders of magnitude - the usual symptom of a model that does not quite fit."],
  ["BitNet (b1.58)", "A model family trained from the start with ternary weights (-1, 0, +1), about 1.58 bits per weight. Because training compensates for the rounding, it works where squeezing a normal model to 1 bit would destroy it."],
  ["Ternary weights", "Weights limited to three values: negative one, zero, and positive one. The model learns around this constraint during training instead of suffering it afterward."],
  ["Importance matrix", "A table of which weights matter most for output quality, measured by running calibration text through the original model. IQ-format quants spend their bits where the matrix says it counts."],
  ["IQ quants (IQ2/IQ3)", "GGUF formats between 2 and 3 bits that use an importance matrix. At the same size they outperform older Q2_K/Q3_K formats because the important weights keep more precision."],
  ["Calibration dataset", "A few hundred kilobytes of representative text run through a model before importance-matrix quantization. Match it to your workload: docs for a docs assistant, code for a coding assistant."],
  ["RAG", "Retrieval-augmented generation: fetching your documents into the prompt so answers use them."],
  ["Router", "The component that probes, benchmarks, and selects the fastest inference backend."],
  ["Sandboxing", "Running operations under enforced resource and permission limits."],
  ["Session", "One working conversation with its chosen set of enabled modules."],
  ["SLM", "Small language model: runs on ordinary hardware; the primary target of this platform."],
  ["Smoke test", "A fast automated suite verifying each part still works; all run offline."],
  ["Speculative decoding", "A speed technique: a tiny model drafts tokens, the main model approves them in parallel."],
  ["StateGraph", "stitaP's graph orchestration: typed channels, nodes, conditional edges, loops, checkpoints."],
  ["Swarm", "Multiple agents with roles cooperating on one goal through a blackboard."],
  ["System prompt", "Opening instructions placed before every turn, shaping behavior; grown by enabled modules."],
  ["Ticket", "A tracked unit of work in Jira or similar systems."],
  ["Token", "A text chunk models read and write; roughly three-quarters of an English word."],
  ["Tool", "A named capability agents call, with declared inputs, outputs, and permissions."],
  ["Topologies", "Arrangements for connecting swarm workers: hierarchical, mesh, pipeline, star, ring."],
  ["Trace", "A recorded span tree of one run with timing and token accounting."],
  ["Typecheck", "Automated static analysis catching code mistakes before execution."],
  ["User story", "A unit of desired functionality with acceptance criteria, small enough for one agent pass."],
  ["Vector index", "Storage for embeddings enabling similarity search; Convex hosts stitaP's searchable captures."],
  ["Verifier", "The swarm role responsible for final acceptance against evidence."],
  ["Waterfall", "A timeline visualization of spans showing where a run spent time and tokens."],
  ["Webhook", "An outbound notification channel delivering alerts to a URL you provide."],
  ["Window starvation", "Failure mode where enabled overhead exceeds the context window, collapsing generation."],
  ["KV-cache quantization", "Storing the cache notes at 8- or 4-bit instead of FP16, halving or quartering context memory at a small accuracy cost. Useful for long sessions on tight machines."],
  ["Grouped-query attention (GQA)", "A model design that shares key and value notes across groups of attention heads, shrinking the KV cache per token. Common in newer long-context models."],
  ["Activations", "The intermediate results computed between model layers for the current token. They exist for an instant and are thrown away, but the runtime must reserve a fixed buffer large enough for the biggest one - this is the working space."],
];
